insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Ideal gas law: Energy associated with a gas', 'According to the assumptions of the kinetic theory of ideal gases, one can consider that there are no intermolecular attractions between the molecules, or atoms, of an ideal gas. In other words, its potential energy is zero. Hence, all the energy possessed by the gas is the kinetic energy of the molecules, or atoms, of the gas. This corresponds to the kinetic energy of n moles of a monoatomic gas having 3 degrees of freedom: x, y, z. The table here below gives this relationship for different amounts of a monoatomic gas.', 'Wikipedia: Ideal gas law', 'https://en.wikipedia.org/w/index.php?title=Ideal_gas_law&oldid=1376350823', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'According to the assumptions of the kinetic theory of ideal gases, one can consider that there are no intermolecular attractions between the molecules, or atoms, of an ideal gas. In other words, its potential energy is zero. Hence, all the energy possessed by the gas is the kinetic energy of the molecules, or atoms, of the gas. This corresponds to the kinetic energy of n moles of a monoatomic gas having 3 degrees of freedom: x, y, z. The table here below gives this relationship for different amounts of a monoatomic gas.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Ideal gas law: Applications to thermodynamic processes', 'The table below essentially simplifies the ideal gas equation for a particular process, making the equation easier to solve using numerical methods. A thermodynamic process is defined as a system that moves from state 1 to state 2, where the state number is denoted by a subscript. As shown in the first column of the table, basic thermodynamic processes are defined such that one of the gas properties (P, V, T, S, or H) is constant throughout the process. For a given thermodynamic process, in order to specify the extent of a particular process, one of the properties ratios (which are listed under the column labeled "known ratio") must be specified (either directly or indirectly). Also, the property for which the ratio is known must be distinct from the property held constant in the previous column (otherwise the ratio would be unity, and not enough information would be available to simplify the gas law equation). In the final three columns, the properties (p, V, or T) at state 2 can be calculated from the properties at state 1 using the equations listed.', 'Wikipedia: Ideal gas law', 'https://en.wikipedia.org/w/index.php?title=Ideal_gas_law&oldid=1376350823', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'The table below essentially simplifies the ideal gas equation for a particular process, making the equation easier to solve using numerical methods. A thermodynamic process is defined as a system that moves from state 1 to state 2, where the state number is denoted by a subscript. As shown in the first column of the table, basic thermodynamic processes are defined such that one of the gas properties (P, V, T, S, or H) is constant throughout the process. For a given thermodynamic process, in order to specify the extent of a particular process, one of the properties ratios (which are listed under the column labeled "known ratio") must be specified (either directly or indirectly). Also, the property for which the ratio is known must be distinct from the property held constant in the previous column (otherwise the ratio would be unity, and not enough information would be available to simplify the gas law equation). In the final three columns, the properties (p, V, or T) at state 2 can be calculated from the properties at state 1 using the equations listed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility', 'In chemistry, solubility is the ability of a substance, the solute, to form a solution with another substance, the solvent. Insolubility is the opposite property, the inability of the solute to form such a solution. The extent of the solubility of a substance in a specific solvent is generally measured as the concentration of the solute in a saturated solution, one in which no more solute can be dissolved. At this point, the two substances are said to be at the solubility equilibrium. For some solutes and solvents, there may be no such limit, in which case the two substances are said to be "miscible in all proportions" (or just "miscible"). The solute can be a solid, a liquid, or a gas, while the solvent is usually solid or liquid. Both may be pure substances, or may themselves be solutions. Gases are always miscible in all proportions, except in very extreme situations, and a solid or liquid can be "dissolved" in a gas only by passing into the gaseous state first.', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'In chemistry, solubility is the ability of a substance, the solute, to form a solution with another substance, the solvent. Insolubility is the opposite property, the inability of the solute to form such a solution. The extent of the solubility of a substance in a specific solvent is generally measured as the concentration of the solute in a saturated solution, one in which no more solute can be dissolved. At this point, the two substances are said to be at the solubility equilibrium. For some solutes and solvents, there may be no such limit, in which case the two substances are said to be "miscible in all proportions" (or just "miscible"). The solute can be a solid, a liquid, or a gas, while the solvent is usually solid or liquid. Both may be pure substances, or may themselves be solutions. Gases are always miscible in all proportions, except in very extreme situations, and a solid or liquid can be "dissolved" in a gas only by passing into the gaseous state first.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility', 'The solubility mainly depends on the composition of solute and solvent (including their pH and the presence of other dissolved substances) as well as on temperature and pressure. The dependency can often be explained in terms of interactions between the particles (atoms, molecules, or ions) of the two substances, and of thermodynamic concepts such as enthalpy and entropy. Under certain conditions, the concentration of the solute can exceed its usual solubility limit. The result is a supersaturated solution, which is metastable and will rapidly exclude the excess solute if a suitable nucleation site appears. The concept of solubility does not apply when there is an irreversible chemical reaction between the two substances, such as the reaction of calcium hydroxide with hydrochloric acid; even though one might say, informally, that one "dissolved" the other. The solubility is also not the same as the rate of solution, which is how fast a solid solute dissolves in a liquid solvent. This property depends on many other variables, such as the physical form of the two substances and the manner and intensity of mixing.', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'The solubility mainly depends on the composition of solute and solvent (including their pH and the presence of other dissolved substances) as well as on temperature and pressure. The dependency can often be explained in terms of interactions between the particles (atoms, molecules, or ions) of the two substances, and of thermodynamic concepts such as enthalpy and entropy. Under certain conditions, the concentration of the solute can exceed its usual solubility limit. The result is a supersaturated solution, which is metastable and will rapidly exclude the excess solute if a suitable nucleation site appears. The concept of solubility does not apply when there is an irreversible chemical reaction between the two substances, such as the reaction of calcium hydroxide with hydrochloric acid; even though one might say, informally, that one "dissolved" the other. The solubility is also not the same as the rate of solution, which is how fast a solid solute dissolves in a liquid solvent. This property depends on many other variables, such as the physical form of the two substances and the manner and intensity of mixing.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility', 'The concept and measure of solubility are extremely important in many sciences besides chemistry, such as geology, biology, physics, and oceanography, as well as in engineering, medicine, agriculture, and even in non-technical activities like painting, cleaning, cooking, and brewing. Most chemical reactions of scientific, industrial, or practical interest only happen after the reagents have been dissolved in a suitable solvent. Water is by far the most common such solvent. The term "soluble" is sometimes used for materials that can form colloidal suspensions of very fine solid particles in a liquid. The quantitative solubility of such substances is generally not well-defined, however.', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'The concept and measure of solubility are extremely important in many sciences besides chemistry, such as geology, biology, physics, and oceanography, as well as in engineering, medicine, agriculture, and even in non-technical activities like painting, cleaning, cooking, and brewing. Most chemical reactions of scientific, industrial, or practical interest only happen after the reagents have been dissolved in a suitable solvent. Water is by far the most common such solvent. The term "soluble" is sometimes used for materials that can form colloidal suspensions of very fine solid particles in a liquid. The quantitative solubility of such substances is generally not well-defined, however.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility: Quantification of solubility', 'The solubility of a specific solute in a specific solvent is generally expressed as the concentration of a saturated solution of the two. Any of the several ways of expressing concentration of solutions can be used, such as the mass, volume, or amount in moles of the solute for a specific mass, volume, or mole amount of the solvent or of the solution.', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'The solubility of a specific solute in a specific solvent is generally expressed as the concentration of a saturated solution of the two. Any of the several ways of expressing concentration of solutions can be used, such as the mass, volume, or amount in moles of the solute for a specific mass, volume, or mole amount of the solvent or of the solution.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility: Per quantity of solvent', 'In particular, chemical handbooks often express the solubility as grams of solute per 100 millilitres of solvent (g/(100 mL), often written as g/100 ml), or as grams of solute per decilitre of solvent (g/dL); or, less commonly, as grams of solute per litre of solvent (g/L). The quantity of solvent can instead be expressed in mass, as grams of solute per 100 grams of solvent (g/(100 g), often written as g/100 g), or as grams of solute per kilogram of solvent (g/kg). The number may be expressed as a percentage in this case, and the abbreviation "w/w" may be used to indicate "weight per weight". (The values in g/L and g/kg are similar for water, but that may not be the case for other solvents.) Alternatively, the solubility of a solute can be expressed in moles instead of mass. For example, if the quantity of solvent is given in kilograms, the value is the molality of the solution (mol/kg).', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'In particular, chemical handbooks often express the solubility as grams of solute per 100 millilitres of solvent (g/(100 mL), often written as g/100 ml), or as grams of solute per decilitre of solvent (g/dL); or, less commonly, as grams of solute per litre of solvent (g/L). The quantity of solvent can instead be expressed in mass, as grams of solute per 100 grams of solvent (g/(100 g), often written as g/100 g), or as grams of solute per kilogram of solvent (g/kg). The number may be expressed as a percentage in this case, and the abbreviation "w/w" may be used to indicate "weight per weight". (The values in g/L and g/kg are similar for water, but that may not be the case for other solvents.) Alternatively, the solubility of a solute can be expressed in moles instead of mass. For example, if the quantity of solvent is given in kilograms, the value is the molality of the solution (mol/kg).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility: Per quantity of solution', 'The solubility of a substance in a liquid may also be expressed as the quantity of solute per quantity of solution, rather than of solvent. For example, following the common practice in titration, it may be expressed as moles of solute per litre of solution (mol/L), the molarity of the latter. In more specialized contexts the solubility may be given by the mole fraction (moles of solute per total moles of solute plus solvent) or by the mass fraction at equilibrium (mass of solute per mass of solute plus solvent). Both are dimensionless numbers between 0 and 1 which may be expressed as percentages (%).', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'The solubility of a substance in a liquid may also be expressed as the quantity of solute per quantity of solution, rather than of solvent. For example, following the common practice in titration, it may be expressed as moles of solute per litre of solution (mol/L), the molarity of the latter. In more specialized contexts the solubility may be given by the mole fraction (moles of solute per total moles of solute plus solvent) or by the mass fraction at equilibrium (mass of solute per mass of solute plus solvent). Both are dimensionless numbers between 0 and 1 which may be expressed as percentages (%).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility: Liquid and gaseous solutes', 'For solutions of liquids or gases in liquids, the quantities of both substances may be given volume rather than mass or mole amount; such as litre of solute per litre of solvent, or litre of solute per litre of solution. The value may be given as a percentage, and the abbreviation "v/v" for "volume per volume" may be used to indicate this choice.', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'For solutions of liquids or gases in liquids, the quantities of both substances may be given volume rather than mass or mole amount; such as litre of solute per litre of solvent, or litre of solute per litre of solution. The value may be given as a percentage, and the abbreviation "v/v" for "volume per volume" may be used to indicate this choice.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Solubility: Conversion of solubility values', 'Conversion between these various ways of measuring solubility may not be trivial, since it may require knowing the density of the solution—which is often not measured, and cannot be predicted. While the total mass is conserved by dissolution, the final volume may be different from both the volume of the solvent and the sum of the two volumes. Moreover, many solids (such as acids and salts) will dissociate in non-trivial ways when dissolved; conversely, the solvent may form coordination complexes with the molecules or ions of the solute. In those cases, the sum of the moles of molecules of solute and solvent is not really the total moles of independent particles solution. To sidestep that problem, the solubility per mole of solution is usually computed and quoted as if the solute does not dissociate or form complexes—that is, by pretending that the mole amount of solution is the sum of the mole amounts of the two substances.', 'Wikipedia: Solubility', 'https://en.wikipedia.org/w/index.php?title=Solubility&oldid=1369621201', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Conversion between these various ways of measuring solubility may not be trivial, since it may require knowing the density of the solution—which is often not measured, and cannot be predicted. While the total mass is conserved by dissolution, the final volume may be different from both the volume of the solvent and the sum of the two volumes. Moreover, many solids (such as acids and salts) will dissociate in non-trivial ways when dissolved; conversely, the solvent may form coordination complexes with the molecules or ions of the solute. In those cases, the sum of the moles of molecules of solute and solvent is not really the total moles of independent particles solution. To sidestep that problem, the solubility per mole of solution is usually computed and quoted as if the solute does not dissociate or form complexes—that is, by pretending that the mole amount of solution is the sum of the mole amounts of the two substances.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties', 'In chemistry, colligative properties are those properties of solutions that depend on the ratio of the number of solute particles to the number of solvent particles in a solution, and not on the nature of the chemical species present. The number ratio can be related to the various units for concentration of a solution such as molarity, molality, normality, etc. The assumption that solution properties are independent of nature of solute particles is exact only for ideal solutions, which are solutions that exhibit thermodynamic properties analogous to those of an ideal gas, and is approximate for dilute real solutions. In other words, colligative properties are a set of solution properties that can be reasonably approximated by the assumption that the solution is ideal.', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'In chemistry, colligative properties are those properties of solutions that depend on the ratio of the number of solute particles to the number of solvent particles in a solution, and not on the nature of the chemical species present. The number ratio can be related to the various units for concentration of a solution such as molarity, molality, normality, etc. The assumption that solution properties are independent of nature of solute particles is exact only for ideal solutions, which are solutions that exhibit thermodynamic properties analogous to those of an ideal gas, and is approximate for dilute real solutions. In other words, colligative properties are a set of solution properties that can be reasonably approximated by the assumption that the solution is ideal.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties', 'Only properties which result from the dissolution of a nonvolatile solute in a volatile liquid solvent are considered. They are essentially solvent properties which are changed by the presence of the solute. The solute particles displace some solvent molecules in the liquid phase and thereby reduce the concentration of solvent and increase its entropy, so that the colligative properties are independent of the nature of the solute. The word colligative is derived from the Latin colligatus meaning bound together. This indicates that all colligative properties have a common feature, namely that they are related only to the number of solute molecules relative to the number of solvent molecules and not to the nature of the solute. For a given solute-solvent mass ratio, all colligative properties are inversely proportional to solute molar mass. Measurement of colligative properties for a dilute solution of a non-ionized solute such as urea or glucose in water or another solvent can lead to determinations of relative molar masses, both for small molecules and for polymers which cannot be studied by other means. Alternatively, measurements for ionized solutes can lead to an estimation of the percentage of dissociation taking place.', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Only properties which result from the dissolution of a nonvolatile solute in a volatile liquid solvent are considered. They are essentially solvent properties which are changed by the presence of the solute. The solute particles displace some solvent molecules in the liquid phase and thereby reduce the concentration of solvent and increase its entropy, so that the colligative properties are independent of the nature of the solute. The word colligative is derived from the Latin colligatus meaning bound together. This indicates that all colligative properties have a common feature, namely that they are related only to the number of solute molecules relative to the number of solvent molecules and not to the nature of the solute. For a given solute-solvent mass ratio, all colligative properties are inversely proportional to solute molar mass. Measurement of colligative properties for a dilute solution of a non-ionized solute such as urea or glucose in water or another solvent can lead to determinations of relative molar masses, both for small molecules and for polymers which cannot be studied by other means. Alternatively, measurements for ionized solutes can lead to an estimation of the percentage of dissociation taking place.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties', 'Colligative properties are studied mostly for dilute solutions, whose behavior may be approximated as that of an ideal solution. In fact, all of the properties listed above are colligative only in the dilute limit: at higher concentrations, the freezing point depression, boiling point elevation, vapor pressure elevation or depression, and osmotic pressure are all dependent on the chemical nature of the solvent and the solute.', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Colligative properties are studied mostly for dilute solutions, whose behavior may be approximated as that of an ideal solution. In fact, all of the properties listed above are colligative only in the dilute limit: at higher concentrations, the freezing point depression, boiling point elevation, vapor pressure elevation or depression, and osmotic pressure are all dependent on the chemical nature of the solvent and the solute.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties: Relative lowering of vapor pressure', 'A vapor is a substance in a gaseous state at a temperature lower than its critical point. Vapor pressure is the pressure exerted by a vapor in thermodynamic equilibrium with its solid or liquid state. The vapor pressure of a solvent is lowered when a non-volatile solute is dissolved in it to form a solution. For an ideal solution, the equilibrium vapor pressure is given by Raoult''s law as is the vapor pressure of the pure component (i= A, B,...) and For a solution with a solvent (A) and one non-volatile solute (B), If the solute dissociates in solution, then the number of moles of solute is increased by the van ''t Hoff factor , which represents the true number of solute particles for each formula unit. For example, the strong electrolyte MgCl2 dissociates into one Mg2+ ion and two Cl− ions, so that if ionization is complete, i = 3 and is calculated with moles of solute i times initial moles and moles of solvent same as initial moles of solvent before dissociation. The measured colligative properties show that i is somewhat less than 3 due to ion association.', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'A vapor is a substance in a gaseous state at a temperature lower than its critical point. Vapor pressure is the pressure exerted by a vapor in thermodynamic equilibrium with its solid or liquid state. The vapor pressure of a solvent is lowered when a non-volatile solute is dissolved in it to form a solution. For an ideal solution, the equilibrium vapor pressure is given by Raoult''s law as is the vapor pressure of the pure component (i= A, B,...) and For a solution with a solvent (A) and one non-volatile solute (B), If the solute dissociates in solution, then the number of moles of solute is increased by the van ''t Hoff factor , which represents the true number of solute particles for each formula unit. For example, the strong electrolyte MgCl2 dissociates into one Mg2+ ion and two Cl− ions, so that if ionization is complete, i = 3 and is calculated with moles of solute i times initial moles and moles of solvent same as initial moles of solvent before dissociation. The measured colligative properties show that i is somewhat less than 3 due to ion association.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties: Boiling point and freezing point', 'Addition of solute to form a solution stabilizes the solvent in the liquid phase, and lowers the solvent''s chemical potential so that solvent molecules have less tendency to move to the gas or solid phases. As a result, liquid solutions slightly above the solvent boiling point at a given pressure become stable, which means that the boiling point increases. Similarly, liquid solutions slightly below the solvent freezing point become stable meaning that the freezing point decreases. Both the boiling point elevation and the freezing point depression are proportional to the lowering of vapor pressure in a dilute solution. These properties are colligative in systems where the solute is essentially confined to the liquid phase. Boiling point elevation (like vapor pressure lowering) is colligative for non-volatile solutes where the solute presence in the gas phase is negligible. Freezing point depression is colligative for most solutes since very few solutes dissolve appreciably in solid solvents.', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Addition of solute to form a solution stabilizes the solvent in the liquid phase, and lowers the solvent''s chemical potential so that solvent molecules have less tendency to move to the gas or solid phases. As a result, liquid solutions slightly above the solvent boiling point at a given pressure become stable, which means that the boiling point increases. Similarly, liquid solutions slightly below the solvent freezing point become stable meaning that the freezing point decreases. Both the boiling point elevation and the freezing point depression are proportional to the lowering of vapor pressure in a dilute solution. These properties are colligative in systems where the solute is essentially confined to the liquid phase. Boiling point elevation (like vapor pressure lowering) is colligative for non-volatile solutes where the solute presence in the gas phase is negligible. Freezing point depression is colligative for most solutes since very few solutes dissolve appreciably in solid solvents.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties: Boiling point elevation (ebullioscopy)', 'The boiling point of a liquid at a given external pressure is the temperature ( ) at which the vapor pressure of the liquid equals the external pressure. The normal boiling point is the boiling point at a pressure equal to 1 atm. The boiling point of a pure solvent is increased by the addition of a non-volatile solute, and the elevation can be measured by ebullioscopy. It is found that Here i is the van ''t Hoff factor as above, Kb is the ebullioscopic constant of the solvent (equal to 0.512 °C kg/mol for water), and m is the molality of the solution. The boiling point is the temperature at which there is equilibrium between liquid and gas phases. At the boiling point, the number of gas molecules condensing to liquid equals the number of liquid molecules evaporating to gas. Adding a solute dilutes the concentration of the liquid molecules and reduces the rate of evaporation. To compensate for this and re-attain equilibrium, the boiling point occurs at a higher temperature. If the solution is assumed to be an ideal solution, Kb can be evaluated from the thermodynamic condition for liquid-vapor equilibrium. At the boiling point, the chemical potential μA of the solvent in the solution phase equals the chemical potential in the pure vapor phase above the solution.', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'The boiling point of a liquid at a given external pressure is the temperature ( ) at which the vapor pressure of the liquid equals the external pressure. The normal boiling point is the boiling point at a pressure equal to 1 atm. The boiling point of a pure solvent is increased by the addition of a non-volatile solute, and the elevation can be measured by ebullioscopy. It is found that Here i is the van ''t Hoff factor as above, Kb is the ebullioscopic constant of the solvent (equal to 0.512 °C kg/mol for water), and m is the molality of the solution. The boiling point is the temperature at which there is equilibrium between liquid and gas phases. At the boiling point, the number of gas molecules condensing to liquid equals the number of liquid molecules evaporating to gas. Adding a solute dilutes the concentration of the liquid molecules and reduces the rate of evaporation. To compensate for this and re-attain equilibrium, the boiling point occurs at a higher temperature. If the solution is assumed to be an ideal solution, Kb can be evaluated from the thermodynamic condition for liquid-vapor equilibrium. At the boiling point, the chemical potential μA of the solvent in the solution phase equals the chemical potential in the pure vapor phase above the solution.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties: Boiling point elevation (ebullioscopy)', ', where R is the molar gas constant, M is the solvent molar mass and ΔHvap is the solvent molar enthalpy of vaporization.', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = ', where R is the molar gas constant, M is the solvent molar mass and ΔHvap is the solvent molar enthalpy of vaporization.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Colligative properties: Freezing point depression (cryoscopy)', ') of a pure solvent is lowered by the addition of a solute which is insoluble in the solid solvent, and the measurement of this difference is called cryoscopy. It is found that Here Kf is the cryoscopic constant (equal to 1.86 °C kg/mol for the freezing point of water), i is the van ''t Hoff factor, and m the molality (in mol/kg). This predicts the melting of ice by road salt. In the liquid solution, the solvent is diluted by the addition of a solute, so that fewer molecules are available to freeze. Re-establishment of equilibrium is achieved at a lower temperature at which the rate of freezing becomes equal to the rate of liquefying. At the lower freezing point, the vapor pressure of the liquid is equal to the vapor pressure of the corresponding solid, and the chemical potentials of the two phases are equal as well. The equality of chemical potentials permits the evaluation of the cryoscopic constant as', 'Wikipedia: Colligative properties', 'https://en.wikipedia.org/w/index.php?title=Colligative_properties&oldid=1323617629', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = ') of a pure solvent is lowered by the addition of a solute which is insoluble in the solid solvent, and the measurement of this difference is called cryoscopy. It is found that Here Kf is the cryoscopic constant (equal to 1.86 °C kg/mol for the freezing point of water), i is the van ''t Hoff factor, and m the molality (in mol/kg). This predicts the melting of ice by road salt. In the liquid solution, the solvent is diluted by the addition of a solute, so that fewer molecules are available to freeze. Re-establishment of equilibrium is achieved at a lower temperature at which the rate of freezing becomes equal to the rate of liquefying. At the lower freezing point, the vapor pressure of the liquid is equal to the vapor pressure of the corresponding solid, and the chemical potentials of the two phases are equal as well. The equality of chemical potentials permits the evaluation of the cryoscopic constant as');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Osmotic pressure', 'Osmotic pressure is the minimum pressure which needs to be applied to a solution to prevent the inward flow of its pure solvent across a semipermeable membrane. Potential osmotic pressure is the maximum osmotic pressure that could develop in a solution if it was not separated from its pure solvent by a semipermeable membrane. It is the difference between hydrostatic pressures of the solution and the pure solvent. Osmosis occurs when two solutions containing different concentrations of solute are separated by a selectively permeable membrane. Solvent molecules pass preferentially through the membrane from the low-concentration solution to the solution with higher solute concentration. The transfer of solvent molecules continues until osmotic equilibrium is attained.', 'Wikipedia: Osmotic pressure', 'https://en.wikipedia.org/w/index.php?title=Osmotic_pressure&oldid=1381271659', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Osmotic pressure is the minimum pressure which needs to be applied to a solution to prevent the inward flow of its pure solvent across a semipermeable membrane. Potential osmotic pressure is the maximum osmotic pressure that could develop in a solution if it was not separated from its pure solvent by a semipermeable membrane. It is the difference between hydrostatic pressures of the solution and the pure solvent. Osmosis occurs when two solutions containing different concentrations of solute are separated by a selectively permeable membrane. Solvent molecules pass preferentially through the membrane from the low-concentration solution to the solution with higher solute concentration. The transfer of solvent molecules continues until osmotic equilibrium is attained.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Osmotic pressure: Theory and measurement', 'Jacobus van ''t Hoff derived thermodynamically a quantitative relationship between osmotic pressure and solute concentration, expressed in the following equation, where For ideal solutions of low concentration, we can approximate this equation as is osmotic pressure, i is the dimensionless van ''t Hoff index, c is the molar concentration of solute, R is the ideal gas constant, and T is the absolute temperature (usually in kelvins). This formula applies when the solute concentration is sufficiently low that the solution can be treated as an ideal solution. The proportionality to concentration means that osmotic pressure is a colligative property. Note the similarity of this formula to the ideal gas law in the form where n is the total number of moles of gas molecules in the volume V, and n/V is the molar concentration of gas molecules. Harmon Northrop Morse and Frazer showed that the equation applied to more concentrated solutions if the unit of concentration was molal rather than molar; so when the molality is used this equation has been called the Morse equation. For more concentrated solutions the van ''t Hoff equation can be extended as a power series in solute concentration, c. To a first approximation,', 'Wikipedia: Osmotic pressure', 'https://en.wikipedia.org/w/index.php?title=Osmotic_pressure&oldid=1381271659', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Jacobus van ''t Hoff derived thermodynamically a quantitative relationship between osmotic pressure and solute concentration, expressed in the following equation, where For ideal solutions of low concentration, we can approximate this equation as is osmotic pressure, i is the dimensionless van ''t Hoff index, c is the molar concentration of solute, R is the ideal gas constant, and T is the absolute temperature (usually in kelvins). This formula applies when the solute concentration is sufficiently low that the solution can be treated as an ideal solution. The proportionality to concentration means that osmotic pressure is a colligative property. Note the similarity of this formula to the ideal gas law in the form where n is the total number of moles of gas molecules in the volume V, and n/V is the molar concentration of gas molecules. Harmon Northrop Morse and Frazer showed that the equation applied to more concentrated solutions if the unit of concentration was molal rather than molar; so when the molality is used this equation has been called the Morse equation. For more concentrated solutions the van ''t Hoff equation can be extended as a power series in solute concentration, c. To a first approximation,');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Osmotic pressure: Theory and measurement', 'is the ideal pressure and A is an empirical parameter. The value of the parameter A (and of parameters from higher-order approximations) can be used to calculate Pitzer parameters. Empirical parameters are used to quantify the behavior of solutions of ionic and non-ionic solutes which are not ideal solutions in the thermodynamic sense. The Pfeffer cell has been developed for the measurement of osmotic pressure.', 'Wikipedia: Osmotic pressure', 'https://en.wikipedia.org/w/index.php?title=Osmotic_pressure&oldid=1381271659', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'is the ideal pressure and A is an empirical parameter. The value of the parameter A (and of parameters from higher-order approximations) can be used to calculate Pitzer parameters. Empirical parameters are used to quantify the behavior of solutions of ionic and non-ionic solutes which are not ideal solutions in the thermodynamic sense. The Pfeffer cell has been developed for the measurement of osmotic pressure.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Osmotic pressure: Applications', 'Osmotic pressure measurement may be used for the determination of molecular weights. Osmotic pressure is an important factor affecting biological cells. Osmoregulation is the homeostasis mechanism of an organism to reach balance in osmotic pressure. Hypertonicity is the presence of a solution that causes cells to shrink. Hypotonicity is the presence of a solution that causes cells to swell. Isotonicity is the presence of a solution that produces no change in cell volume. When a biological cell is in a hypotonic environment, the cell interior accumulates water, water flows across the cell membrane into the cell, causing it to expand. In plant cells, the cell wall restricts the expansion, resulting in pressure on the cell wall from within called turgor pressure. Turgor pressure allows herbaceous plants to stand upright. It is also the determining factor for how plants regulate the aperture of their stomata. In animal cells excessive osmotic pressure can result in cytolysis due to the absence of a cell wall.', 'Wikipedia: Osmotic pressure', 'https://en.wikipedia.org/w/index.php?title=Osmotic_pressure&oldid=1381271659', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Osmotic pressure measurement may be used for the determination of molecular weights. Osmotic pressure is an important factor affecting biological cells. Osmoregulation is the homeostasis mechanism of an organism to reach balance in osmotic pressure. Hypertonicity is the presence of a solution that causes cells to shrink. Hypotonicity is the presence of a solution that causes cells to swell. Isotonicity is the presence of a solution that produces no change in cell volume. When a biological cell is in a hypotonic environment, the cell interior accumulates water, water flows across the cell membrane into the cell, causing it to expand. In plant cells, the cell wall restricts the expansion, resulting in pressure on the cell wall from within called turgor pressure. Turgor pressure allows herbaceous plants to stand upright. It is also the determining factor for how plants regulate the aperture of their stomata. In animal cells excessive osmotic pressure can result in cytolysis due to the absence of a cell wall.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Osmotic pressure: Applications', 'Osmotic pressure is the basis of filtering ("reverse osmosis"), a process commonly used in water purification. The water to be purified is placed in a chamber and put under an amount of pressure greater than the osmotic pressure exerted by the water and the solutes dissolved in it. Part of the chamber opens to a differentially permeable membrane that lets water molecules through, but not the solute particles. The osmotic pressure of ocean water is approximately 27 atm. Reverse osmosis desalinates fresh water from ocean salt water and is applied globally on a very large scale.', 'Wikipedia: Osmotic pressure', 'https://en.wikipedia.org/w/index.php?title=Osmotic_pressure&oldid=1381271659', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Osmotic pressure is the basis of filtering ("reverse osmosis"), a process commonly used in water purification. The water to be purified is placed in a chamber and put under an amount of pressure greater than the osmotic pressure exerted by the water and the solutes dissolved in it. Part of the chamber opens to a differentially permeable membrane that lets water molecules through, but not the solute particles. The osmotic pressure of ocean water is approximately 27 atm. Reverse osmosis desalinates fresh water from ocean salt water and is applied globally on a very large scale.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Osmotic pressure: Derivation of the van ''t Hoff formula', 'Consider the system at the point when it has reached equilibrium. The condition for this is that the chemical potential of the solvent (since only it is free to flow toward equilibrium) on both sides of the membrane is equal. The compartment containing the pure solvent has a chemical potential of is the pressure. On the other side, in the compartment containing the solute, the chemical potential of the solvent depends on the mole fraction of the solvent, . We can therefore write the chemical potential of the solvent as is defined as the osmotic pressure exerted by the solutes. Holding the pressure, the addition of solute decreases the chemical potential (an entropic effect). Thus, the pressure of the solution has to be increased in an effort to compensate the loss of the chemical potential. , the osmotic pressure, we consider equilibrium between a solution containing solute and pure water. is also known as the activity of the solvent, which for water is the water activity . The addition to the pressure is expressed through the expression for the energy of expansion: is the molar volume (m³/mol). Inserting the expression presented above into the chemical potential equation for the entire system and rearranging will arrive at:', 'Wikipedia: Osmotic pressure', 'https://en.wikipedia.org/w/index.php?title=Osmotic_pressure&oldid=1381271659', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
