insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Osmotic pressure: Derivation of the van ''t Hoff formula', 'The activity coefficient is a function of concentration and temperature, but in the case of dilute mixtures, it is often very close to 1.0, so For aqueous solutions of salts, ionisation must be taken into account. For example, 1 mole of NaCl ionises to 2 moles of ions.', 'Wikipedia: Osmotic pressure', 'https://en.wikipedia.org/w/index.php?title=Osmotic_pressure&oldid=1381271659', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'The activity coefficient is a function of concentration and temperature, but in the case of dilute mixtures, it is often very close to 1.0, so For aqueous solutions of salts, ionisation must be taken into account. For example, 1 mole of NaCl ionises to 2 moles of ions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Raoult''s law', 'Raoult''s law ( law) is a relation of physical chemistry, with implications in thermodynamics. Proposed by French chemist François-Marie Raoult in 1887, it states that the partial pressure of each component of an ideal mixture of liquids is equal to the vapor pressure of the pure component (liquid or solid) multiplied by its mole fraction in the mixture. In consequence, the relative lowering of vapor pressure of a dilute solution of nonvolatile solute is equal to the mole fraction of solute in the solution. Mathematically, Raoult''s law for a single component in an ideal solution is stated as Where two volatile liquids A and B are mixed with each other to form a solution, the vapor phase consists of both components of the solution. Once the components in the solution have reached equilibrium, the total vapor pressure of the solution can be determined by combining Raoult''s law with Dalton''s law of partial pressures to give In other words, the vapor pressure of the solution is the mole-weighted mean of the individual vapour pressures:', 'Wikipedia: Raoult''s law', 'https://en.wikipedia.org/w/index.php?title=Raoult''s_law&oldid=1375228035', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Raoult''s law ( law) is a relation of physical chemistry, with implications in thermodynamics. Proposed by French chemist François-Marie Raoult in 1887, it states that the partial pressure of each component of an ideal mixture of liquids is equal to the vapor pressure of the pure component (liquid or solid) multiplied by its mole fraction in the mixture. In consequence, the relative lowering of vapor pressure of a dilute solution of nonvolatile solute is equal to the mole fraction of solute in the solution. Mathematically, Raoult''s law for a single component in an ideal solution is stated as Where two volatile liquids A and B are mixed with each other to form a solution, the vapor phase consists of both components of the solution. Once the components in the solution have reached equilibrium, the total vapor pressure of the solution can be determined by combining Raoult''s law with Dalton''s law of partial pressures to give In other words, the vapor pressure of the solution is the mole-weighted mean of the individual vapour pressures:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Raoult''s law', 'If a non-volatile solute B (it has zero vapor pressure, so does not evaporate) is dissolved into a solvent A to form an ideal solution, the vapor pressure of the solution will be lower than that of the solvent. In an ideal solution of a nonvolatile solute, the decrease in vapor pressure is directly proportional to the mole fraction of solute: If the solute associates or dissociates in the solution (such as an electrolyte/salt), the expression of the law includes the van ''t Hoff factor as a correction factor. That is, the mole fraction must be calculated using the actual number of particles in solution.', 'Wikipedia: Raoult''s law', 'https://en.wikipedia.org/w/index.php?title=Raoult''s_law&oldid=1375228035', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'If a non-volatile solute B (it has zero vapor pressure, so does not evaporate) is dissolved into a solvent A to form an ideal solution, the vapor pressure of the solution will be lower than that of the solvent. In an ideal solution of a nonvolatile solute, the decrease in vapor pressure is directly proportional to the mole fraction of solute: If the solute associates or dissociates in the solution (such as an electrolyte/salt), the expression of the law includes the van ''t Hoff factor as a correction factor. That is, the mole fraction must be calculated using the actual number of particles in solution.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'gases-solutions', 'Raoult''s law: Principles', 'Raoult''s law is a phenomenological relation that assumes ideal behavior based on the simple microscopic assumption that intermolecular forces between unlike molecules are equal to those between similar molecules, and that their molar volumes are the same: the conditions of an ideal solution. This is analogous to the ideal gas law, which is a limiting law valid when the interactive forces between molecules approach zero, for example as the concentration approaches zero. Raoult''s law is instead valid if the physical properties of the components are identical. The more similar the components are, the more their behavior approaches that described by Raoult''s law. For example, if the two components differ only in isotopic content, then Raoult''s law is essentially exact. Comparing measured vapor pressures to predicted values from Raoult''s law provides information about the true relative strength of intermolecular forces. If the vapor pressure is less than predicted (a negative deviation), fewer molecules of each component than expected have left the solution in the presence of the other component, indicating that the forces between unlike molecules are stronger. The converse is true for positive deviations. For a solution of two liquids A and B, Raoult''s law predicts that if no other gases are present, then the total vapor pressure', 'Wikipedia: Raoult''s law', 'https://en.wikipedia.org/w/index.php?title=Raoult''s_law&oldid=1375228035', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'gases-solutions' and body = 'Raoult''s law is a phenomenological relation that assumes ideal behavior based on the simple microscopic assumption that intermolecular forces between unlike molecules are equal to those between similar molecules, and that their molar volumes are the same: the conditions of an ideal solution. This is analogous to the ideal gas law, which is a limiting law valid when the interactive forces between molecules approach zero, for example as the concentration approaches zero. Raoult''s law is instead valid if the physical properties of the components are identical. The more similar the components are, the more their behavior approaches that described by Raoult''s law. For example, if the two components differ only in isotopic content, then Raoult''s law is essentially exact. Comparing measured vapor pressures to predicted values from Raoult''s law provides information about the true relative strength of intermolecular forces. If the vapor pressure is less than predicted (a negative deviation), fewer molecules of each component than expected have left the solution in the presence of the other component, indicating that the forces between unlike molecules are stronger. The converse is true for positive deviations. For a solution of two liquids A and B, Raoult''s law predicts that if no other gases are present, then the total vapor pressure');
